import webpack from 'webpack';
import { createRequire } from 'node:module';
import { cp, mkdir } from 'node:fs/promises';

const require = createRequire(import.meta.url);
const configs = ['catalog', 'cart', 'shell'].map(name => require(`./${name}/webpack.config.cjs`));
const compiler = webpack(configs);
try {
  const stats = await new Promise((resolve, reject) => {
    compiler.run((error, result) => error ? reject(error) : resolve(result));
  });
  if (stats.hasErrors()) throw new Error(stats.toString({ all: false, errors: true }));
} finally {
  await new Promise((resolve, reject) => compiler.close(error => error ? reject(error) : resolve()));
}
await mkdir(new URL('./dist/shell/', import.meta.url), { recursive: true });
await cp(new URL('./shell/index.html', import.meta.url), new URL('./dist/shell/index.html', import.meta.url));
console.log('Built shell, catalog and cart as three webpack builds.');

const path = require('node:path');
const { ModuleFederationPlugin } = require('webpack').container;

module.exports = {
  mode: 'production',
  devtool: false,
  context: __dirname,
  entry: './src/index.js',
  output: {
    path: path.resolve(__dirname, '../dist/shell'),
    filename: 'app.js',
    chunkFilename: '[name].[contenthash].js',
    publicPath: 'auto',
    uniqueName: 'mf_race_shell',
    clean: true,
  },
  optimization: { minimize: false },
  plugins: [new ModuleFederationPlugin({
    name: 'shell',
    remotes: {
      catalog: 'race_catalog@../catalog/remoteEntry.js',
      cart: 'race_cart@../cart/remoteEntry.js',
    },
  })],
};

import { createNavigator, variantTitle } from './navigator.js';
import { loadRemote, wait } from './loader.js';

const container = document.querySelector('#outlet');
const route = document.querySelector('#route');
const logList = document.querySelector('#log');
const catalogButton = document.querySelector('#catalog');
const cartButton = document.querySelector('#cart');
const runButton = document.querySelector('#run');

function log(message) {
  const item = document.createElement('li');
  item.textContent = message;
  logList.append(item);
}

const show = createNavigator(container, loadRemote, log);
document.querySelector('#variant').textContent = variantTitle;

function navigate(name) {
  // Chỉ đổi hash bên trong app preview, không đổi URL bài docs.
  history.replaceState(null, '', `#/${name}`);
  route.textContent = `#/${name}`;
  return show(name).catch(error => log(`Lỗi tải: ${error.message}`));
}

catalogButton.onclick = () => navigate('catalog');
cartButton.onclick = () => navigate('cart');

runButton.onclick = async () => {
  // Khóa nút trong một lượt thử để không trộn nhiều tình huống.
  catalogButton.disabled = cartButton.disabled = runButton.disabled = true;
  logList.replaceChildren();
  try {
    const loadingCatalog = navigate('catalog');
    await wait(100);
    const loadingCart = navigate('cart');
    await Promise.all([loadingCatalog, loadingCart]);
  } finally {
    catalogButton.disabled = cartButton.disabled = runButton.disabled = false;
  }
};

export function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export async function loadRemote(name) {
  if (name === 'catalog') {
    await wait(1500); // Giả lập catalog tải chậm.
    return import('catalog/App');
  }
  if (name === 'cart') {
    await wait(100); // Giả lập cart tải nhanh.
    return import('cart/App');
  }
  throw new Error(`Remote không được hỗ trợ: ${name}`);
}

export const variantTitle = 'Bản lỗi';

export function createNavigator(container, loadRemote, log) {
  let currentRemote;

  return async function show(name) {
    currentRemote?.unmount();
    currentRemote = undefined;
    container.textContent = `Đang tải ${name}…`;
    log(`Bắt đầu tải ${name}.`);

    const remote = await loadRemote(name);

    // LỖI: trong lúc await, người dùng có thể đã chuyển trang.
    // Catalog cũ vẫn gỡ cart đang hiển thị rồi mount đè lên.
    currentRemote?.unmount();
    container.replaceChildren();
    currentRemote = remote.mount(container);
    log(`Đã mount ${name}.`);
  };
}

const path = require('node:path');
const { ModuleFederationPlugin } = require('webpack').container;

module.exports = {
  mode: 'production',
  devtool: false,
  context: __dirname,
  entry: {},
  output: {
    path: path.resolve(__dirname, '../dist/catalog'),
    publicPath: 'auto',
    uniqueName: 'mf_race_catalog',
    chunkFilename: '[name].[contenthash].js',
    clean: true,
  },
  optimization: { minimize: false },
  plugins: [new ModuleFederationPlugin({
    name: 'race_catalog',
    filename: 'remoteEntry.js',
    exposes: { './App': './src/entry.js' },
  })],
};

export function mount(container) {
  const panel = document.createElement('section');
  panel.dataset.remote = 'catalog';
  const heading = document.createElement('h2');
  heading.textContent = 'Catalog';
  const detail = document.createElement('p');
  detail.textContent = 'Áo thun — 200.000đ';
  panel.append(heading, detail);
  container.append(panel);
  return {
    unmount() { panel.remove(); },
  };
}

